(2932950, 409138, 62187, '<td valign="top">I believe fog is totally a morning thing and I used to hate it when I lived where they had it. I haven''t had to deal with fog in almost 15 years. Your photo is a good representation of fog - I think with advanced editing, you could have improved your photo and cloned out the trailer and evened out the colors around the sun. Still, I like your topic so bonus points for that.</td>', 'I believe fog is totally a morning thing and I used to hate it when I lived where they had it. I haven''t had to deal with fog in almost 15 years. Your photo is a good representation of fog - I think with advanced editing, you could have improved your photo and cloned out the trailer and evened out the colors around the sun. Still, I like your topic so bonus points for that.', '2006-10-16 10:40:04.000000', NULL, 1),
(2932954, 412052, 62187, '<td valign="top">The color is really nice but the white clouds look unatural to me like something went not quite right in post process. Sorry if I''m wrong.</td>', 'The color is really nice but the white clouds look unatural to me like something went not quite right in post process. Sorry if I''m wrong.', '2006-10-16 10:41:52.000000', NULL, 1),
(2932955, 410642, 62187, '<td valign="top">Not a very interesting photo, snapshot like, but...bonus points for totally nailing the challenge.</td>', 'Not a very interesting photo, snapshot like, but...bonus points for totally nailing the challenge.', '2006-10-16 10:42:35.000000', NULL, 1),
(2932957, 410810, 62187, '<td valign="top">The border adds a nice touch.</td>', 'The border adds a nice touch.', '2006-10-16 10:43:21.000000', NULL, 1),
(2932959, 411968, 62187, '<td valign="top">I think this is what they were asking for in the challenge...strong work!</td>', 'I think this is what they were asking for in the challenge...strong work!', '2006-10-16 10:45:13.000000', NULL, 1),
(2932966, 411732, 62187, '<td valign="top">The photo is not bad by any means...I''m not seeing much ''Nature'' - it seems a little over-produced to me.</td>', 'The photo is not bad by any means...I''m not seeing much ''Nature'' - it seems a little over-produced to me.', '2006-10-16 10:46:46.000000', NULL, 1),
(2932971, 412273, 62187, '<td valign="top">Why do graveyard workers need coffee any more then dayshift people? Just teasing, I work the graveyard shift too! The photo is ok, with advance editing I would have cloned out that black spot on the handle.</td>', 'Why do graveyard workers need coffee any more then dayshift people? Just teasing, I work the graveyard shift too! The photo is ok, with advance editing I would have cloned out that black spot on the handle.', '2006-10-16 10:48:51.000000', NULL, 1),
(2932973, 411922, 3102, '<td valign="top">A decently-toned black &amp; white shot... cute kid... but this doesn''t scream "morning" to me in any way, I''m afraid.  I might not have cropped out his hand from the bottom of the frame.  Cute shot, though :)</td>', 'A decently-toned black & white shot... cute kid... but this doesn''t scream "morning" to me in any way, I''m afraid.  I might not have cropped out his hand from the bottom of the frame.  Cute shot, though :)', '2006-10-16 10:49:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2932975, 411908, 3102, '<td valign="top">Definitely how I feel about mornings!  The contrast seems just a little high on this one, losing some of the details of the hammer to the background, and making the white of the clock a little too bright to my eyes.</td>', 'Definitely how I feel about mornings!  The contrast seems just a little high on this one, losing some of the details of the hammer to the background, and making the white of the clock a little too bright to my eyes.', '2006-10-16 10:50:06.000000', NULL, 1),
(2932977, 411178, 3102, '<td valign="top">A good action shot, but to be honest, it doesn''t strike me as a good representation of the challenge, considering this could have easily been shot at any time of the day.  The only connection to the challenge is in the title, and we have to take your word for it.</td>', 'A good action shot, but to be honest, it doesn''t strike me as a good representation of the challenge, considering this could have easily been shot at any time of the day.  The only connection to the challenge is in the title, and we have to take your word for it.', '2006-10-16 10:51:07.000000', NULL, 1),
(2932979, 411219, 3102, '<td valign="top">Well, I''ll admit it may meet the challenge, but I can''t say there''s much that''s appealing about this shot.  I guess in a way this is how I feel in the morning (bleary-eyed, etc.), but I can''t help but think there could be a better way of demonstrating it.  The lens flares, blown out light, etc., just hurt my eyes more than anything :/</td>', 'Well, I''ll admit it may meet the challenge, but I can''t say there''s much that''s appealing about this shot.  I guess in a way this is how I feel in the morning (bleary-eyed, etc.), but I can''t help but think there could be a better way of demonstrating it.  The lens flares, blown out light, etc., just hurt my eyes more than anything :/', '2006-10-16 10:52:48.000000', NULL, 1),
(2932981, 411147, 3102, '<td valign="top">A very pretty and well-exposed scene, although it certainly could have been taken at any time of the day.  It doesn''t really scream "morning" to me.</td>', 'A very pretty and well-exposed scene, although it certainly could have been taken at any time of the day.  It doesn''t really scream "morning" to me.', '2006-10-16 10:53:34.000000', NULL, 1),
(2932984, 409387, 3102, '<td valign="top">The composition is great, but I would have really enjoyed seeing a version of this that wasn''t so heavy on the contrast.</td>', 'The composition is great, but I would have really enjoyed seeing a version of this that wasn''t so heavy on the contrast.', '2006-10-16 10:54:07.000000', NULL, 1),
(2932993, 411583, 16241, '<td valign="top">very pretty.</td>', 'very pretty.', '2006-10-16 10:55:58.000000', NULL, 1),
(2932998, 411855, 53572, '<td valign="top">good lord, this is one of the drugs i''m considering, but i just hate giving myself needles - i did a study this spring and loathed it.  so i think i''m going for one with the epi-pens.  anyway, enough about me...<br/> <br/>it''s a great dea, but i''m not mad on the composition.  the exposure, depth of field, and focus work well, but it''s just a bit spread out and empty for my taste.  perhaps an espresso and the needle would have worked better, as they''re both shots...  plus, with two small things, the imapct would have been much stronger.</td>', 'good lord, this is one of the drugs i''m considering, but i just hate giving myself needles - i did a study this spring and loathed it.  so i think i''m going for one with the epi-pens.  anyway, enough about me... it''s a great dea, but i''m not mad on the composition.  the exposure, depth of field, and focus work well, but it''s just a bit spread out and empty for my taste.  perhaps an espresso and the needle would have worked better, as they''re both shots...  plus, with two small things, the imapct would have been much stronger.', '2006-10-16 10:58:18.000000', NULL, 1),
