(2933614, 412239, 51538, '<td valign="top">Lovely framing.  The zebra foal and mare fit perfectly in the frame.  The mare''s mane parallels the grass in the background in an interesting way. 9.</td>', 'Lovely framing.  The zebra foal and mare fit perfectly in the frame.  The mare''s mane parallels the grass in the background in an interesting way. 9.', '2006-10-16 13:50:21.000000', NULL, 1),
(2933623, 410771, 51538, '<td valign="top">Well this photo of yours really does stand out from the crowd.  The golden sky and lilac terra firma with the sole gull form a nice setting for those mountains.  9.</td>', 'Well this photo of yours really does stand out from the crowd.  The golden sky and lilac terra firma with the sole gull form a nice setting for those mountains.  9.', '2006-10-16 13:52:09.000000', NULL, 1),
