(2933626, 412067, 36403, '<td valign="top">Meets Challenge - 2<br/>Lighting/Composition/Processing - 2<br/>Overall Impression - 2<br/>"WOW" factor - 1<br/>Score: 7</td>', 'Meets Challenge - 2Lighting/Composition/Processing - 2Overall Impression - 2"WOW" factor - 1Score: 7', '2006-10-16 13:52:54.000000', NULL, 1),
