(2933633, 411393, 36403, '<td valign="top">Meets Challenge - 2<br/>Lighting/Composition/Processing - 3<br/>Overall Impression - 2<br/>"WOW" factor - 0<br/>Score: 7</td>', 'Meets Challenge - 2Lighting/Composition/Processing - 3Overall Impression - 2"WOW" factor - 0Score: 7', '2006-10-16 13:54:34.000000', NULL, 1),
(2933639, 412067, 51538, '<td valign="top">This is outstanding and the light really is at a nice angle.  I''m an ex-Londoner and spent many a day cycling across that bridge.  Now what I am thinking is that the light is from a more westerly direction than from the east.  West is evening and east is morning, as far as I remember.  It looks like morning to me yet the light is telling me evening.  Tell me I''m wrong.  Perhaps we''ll not quibble about the time of day and just stick with the overall effect?  OK, then 9.</td>', 'This is outstanding and the light really is at a nice angle.  I''m an ex-Londoner and spent many a day cycling across that bridge.  Now what I am thinking is that the light is from a more westerly direction than from the east.  West is evening and east is morning, as far as I remember.  It looks like morning to me yet the light is telling me evening.  Tell me I''m wrong.  Perhaps we''ll not quibble about the time of day and just stick with the overall effect?  OK, then 9.', '2006-10-16 13:57:37.000000', NULL, 1),
(2933640, 408862, 36403, '<td valign="top">Meets Challenge - 2<br/>Lighting/Composition/Processing - 2<br/>Overall Impression - 1<br/>"WOW" factor - 0<br/>Score: 5</td>', 'Meets Challenge - 2Lighting/Composition/Processing - 2Overall Impression - 1"WOW" factor - 0Score: 5', '2006-10-16 13:57:45.000000', NULL, 1),
(2933642, 412040, 51538, '<td valign="top">Nicely composed and well executed. 9.</td>', 'Nicely composed and well executed. 9.', '2006-10-16 13:57:57.000000', NULL, 1),
(2933646, 411772, 36403, '<td valign="top">Meets Challenge - 2<br/>Lighting/Composition/Processing - 2<br/>Overall Impression - 1<br/>"WOW" factor - 0<br/>Score: 5<br/> <br/>Usually I like a little tilt in a photo, but this one isn''t working for some reason for me... maybe play around the the angle?</td>', 'Meets Challenge - 2Lighting/Composition/Processing - 2Overall Impression - 1"WOW" factor - 0Score: 5 Usually I like a little tilt in a photo, but this one isn''t working for some reason for me... maybe play around the the angle?', '2006-10-16 13:58:38.000000', NULL, 1),
(2933647, 411922, 36403, '<td valign="top">Meets Challenge - 1<br/>Lighting/Composition/Processing - 2<br/>Overall Impression - 2<br/>"WOW" factor - 0<br/>Score: 5</td>', 'Meets Challenge - 1Lighting/Composition/Processing - 2Overall Impression - 2"WOW" factor - 0Score: 5', '2006-10-16 13:59:22.000000', NULL, 1),
