(2936313, 410817, 48248, '<td valign="top">nice lighting and detail</td>', 'nice lighting and detail', '2006-10-17 12:07:26.000000', NULL, 1),
(2936318, 411853, 48248, '<td valign="top">This has alot of potential, but I wish you could have found a leaf that provided a strong focal point.</td>', 'This has alot of potential, but I wish you could have found a leaf that provided a strong focal point.', '2006-10-17 12:10:06.000000', NULL, 1),
