(2936324, 411178, 48248, '<td valign="top">Love the facial expression</td>', 'Love the facial expression', '2006-10-17 12:13:11.000000', NULL, 1),
(2936332, 412092, 48248, '<td valign="top">Beautiful Light and tonal qualities.  I was just at a Wedding Recption there last weekend.  I see some similar qualities in our entries.  Is it possible that you are the photographer that everyone seems to be mistaking my entry for?</td>', 'Beautiful Light and tonal qualities.  I was just at a Wedding Recption there last weekend.  I see some similar qualities in our entries.  Is it possible that you are the photographer that everyone seems to be mistaking my entry for?', '2006-10-17 12:17:53.000000', NULL, 1),
