INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2942690, 409204, 67316, '<td valign="top">The clarity in this photo is brilliant!  Very piercing!  <br/>Ruth Dudley-Carr</td>', 'The clarity in this photo is brilliant!  Very piercing!  Ruth Dudley-Carr', '2006-10-19 00:44:29.000000', NULL, 1),
(2942696, 411204, 35669, '<td valign="top">I really like this and would be interested to see the original to know how you gor it here.  8</td>', 'I really like this and would be interested to see the original to know how you gor it here.  8', '2006-10-19 00:47:01.000000', NULL, 1),
(2942704, 410229, 35669, '<td valign="top">love it</td>', 'love it', '2006-10-19 00:49:00.000000', NULL, 1),
(2942834, 411916, 33672, '<td valign="top">Magnificent photo. Seems like a painting with deep rich tones.</td>', 'Magnificent photo. Seems like a painting with deep rich tones.', '2006-10-19 01:31:33.000000', NULL, 1),
(2942962, 411791, 64446, '<td valign="top">In the morning or in the afternoon? Not sure how you envisioned this image in this challenge...</td>', 'In the morning or in the afternoon? Not sure how you envisioned this image in this challenge...', '2006-10-19 03:19:38.000000', NULL, 1),
(2942984, 411662, 35786, '<td valign="top">I think this could use a little more vividness- try a USM at a high radius (250) and low amount (maybe 10-30) and see how that goes. or you could try one of my faves- a levels layer (don''t adjust anything!) and just set it to overlay. you''ll have to reduce the opacity to around 35% but play with it. It''s a great image to start with for sure :0)</td>', 'I think this could use a little more vividness- try a USM at a high radius (250) and low amount (maybe 10-30) and see how that goes. or you could try one of my faves- a levels layer (don''t adjust anything!) and just set it to overlay. you''ll have to reduce the opacity to around 35% but play with it. It''s a great image to start with for sure :0)', '2006-10-19 03:44:10.000000', NULL, 1),
(2942985, 410728, 35786, '<td valign="top">I love the repeating lines from the shoulder and the wave in the hair lighting is excellent too</td>', 'I love the repeating lines from the shoulder and the wave in the hair lighting is excellent too', '2006-10-19 03:47:11.000000', NULL, 1),
(2943147, 410763, 16046, '<td valign="top">405? sure looks like it. funny</td>', '405? sure looks like it. funny', '2006-10-19 05:48:04.000000', NULL, 1),
(2943274, 410579, 65526, '<td valign="top">very original, so basic its brilliant.</td>', 'very original, so basic its brilliant.', '2006-10-19 08:11:12.000000', NULL, 1),
(2943436, 411916, 51802, '<td valign="top">WOW!  This is absolutely amazing.  I am in awe.</td>', 'WOW!  This is absolutely amazing.  I am in awe.', '2006-10-19 10:29:34.000000', NULL, 1),
(2943486, 412032, 31403, '<td valign="top">beautiful shot - I miss the color, I also think the highlight on the chrome being right behind the cup (main subject) is distracting.  But this is very nice work. 7</td>', 'beautiful shot - I miss the color, I also think the highlight on the chrome being right behind the cup (main subject) is distracting.  But this is very nice work. 7', '2006-10-19 11:00:33.000000', NULL, 1),
(2943493, 412257, 31403, '<td valign="top">great idea here!  Love the concept, and have thought about these kinds of shots for my stock work.  I wonder if you used fill flash if it would make the foreground stronger and balance the image more.</td>', 'great idea here!  Love the concept, and have thought about these kinds of shots for my stock work.  I wonder if you used fill flash if it would make the foreground stronger and balance the image more.', '2006-10-19 11:04:01.000000', NULL, 1),
(2943512, 411672, 31403, '<td valign="top">this image calls to mind when my dad would wake me up very early as a kid - and my body would shiver even though it was warm as we got stuff into the car to go fishing.  A warm and nostalgic memory indeed.<br/> <br/>I find myself wondering what the exposure is here - if you had some poor guy holding very still in that position for a 1/2 second exposure?  Whatever you did it yeilded a very nice image that is worthy of any professional ad campaign.  8</td>', 'this image calls to mind when my dad would wake me up very early as a kid - and my body would shiver even though it was warm as we got stuff into the car to go fishing.  A warm and nostalgic memory indeed. I find myself wondering what the exposure is here - if you had some poor guy holding very still in that position for a 1/2 second exposure?  Whatever you did it yeilded a very nice image that is worthy of any professional ad campaign.  8', '2006-10-19 11:08:16.000000', NULL, 1),
(2943538, 411917, 31403, '<td valign="top">Love the composition and the location here.  The tree framing the city - very nice.<br/> <br/>Selecting the shadows and working them to bring out the details would make<br/>this a stunning image.  Right now the dark sections are muddy and lacking detail.<br/> <br/>If you don''t know, I''m referring to these techniques:<br/>the shadow/highlight filter in CS/2, or the ctrl-alt-~ to select the highlights in earlier versions, then shift-ctr-I to select the dark sections<br/> <br/>Hope that''s helpful 6</td>', 'Love the composition and the location here.  The tree framing the city - very nice. Selecting the shadows and working them to bring out the details would makethis a stunning image.  Right now the dark sections are muddy and lacking detail. If you don''t know, I''m referring to these techniques:the shadow/highlight filter in CS/2, or the ctrl-alt-~ to select the highlights in earlier versions, then shift-ctr-I to select the dark sections Hope that''s helpful 6', '2006-10-19 11:17:12.000000', NULL, 1),
(2943541, 410814, 31403, '<td valign="top">the blob of white on the head is the only fault in this otherwise excellent image!</td>', 'the blob of white on the head is the only fault in this otherwise excellent image!', '2006-10-19 11:18:59.000000', NULL, 1),
(2943565, 410547, 47816, '<td valign="top">The graininess adds loads to this-nice work!</td>', 'The graininess adds loads to this-nice work!', '2006-10-19 11:25:50.000000', NULL, 1),
(2943568, 412068, 31403, '<td valign="top">the blown lights in this are quite distracting.  a solution I''ve found is waiting another 10 - 15 minutes from the lighting in this photo gives more light to the sky, and balances the exposure so you don''t need such a long time - and then the lights don''t burn in like this.<br/> <br/>The balanced light tends to give more color to the sky too.  I shoot a lot of architectural lighting and found this to be the case.<br/> <br/>I always leave helpful tips like this to find later that I''ve given a tip to a photographer who is MUCH better than I.  Sorry if I''ve done that again - just trying to be helpful!  :-)</td>', 'the blown lights in this are quite distracting.  a solution I''ve found is waiting another 10 - 15 minutes from the lighting in this photo gives more light to the sky, and balances the exposure so you don''t need such a long time - and then the lights don''t burn in like this. The balanced light tends to give more color to the sky too.  I shoot a lot of architectural lighting and found this to be the case. I always leave helpful tips like this to find later that I''ve given a tip to a photographer who is MUCH better than I.  Sorry if I''ve done that again - just trying to be helpful!  :-)', '2006-10-19 11:27:37.000000', NULL, 1),
(2943572, 411916, 47816, '<td valign="top">Normally, I don''t like the horizon to split the screen 50/50, but you seem to have made it more dramatic by doing so.  If it weren''t for that duck on the water on the left...</td>', 'Normally, I don''t like the horizon to split the screen 50/50, but you seem to have made it more dramatic by doing so.  If it weren''t for that duck on the water on the left...', '2006-10-19 11:29:12.000000', NULL, 1),
(2943576, 411580, 31403, '<td valign="top">the white halos around the mountains and the derrek make this feel oversharpened to me.  Beautiful scene and great composition on the photography!</td>', 'the white halos around the mountains and the derrek make this feel oversharpened to me.  Beautiful scene and great composition on the photography!', '2006-10-19 11:30:20.000000', NULL, 1),
(2943589, 408915, 31403, '<td valign="top">this is a great take on the challenge, and excellent execution.  I like the grain adding to the gritty nature of his world.  I hope my fellow voters agree - but have little faith they will.  This is very creative and insightful - 8</td>', 'this is a great take on the challenge, and excellent execution.  I like the grain adding to the gritty nature of his world.  I hope my fellow voters agree - but have little faith they will.  This is very creative and insightful - 8', '2006-10-19 11:35:19.000000', NULL, 1),
(2943590, 411919, 6388, '<td valign="top">hm...tough to light indeed without proper studio gear.  The first thing i notice is that it''s strongly lit from the right side.  this casts strong shadows from you, the cup, the bowl, and the paper.  a second source of light (same strength as the first one, or slightly less) placed behind the camera and slightly to the left would fill this in nicely.  Some shadow is good - it adds depth and contour to the photo - but shots like this need more even lighting i think.  Lower light also tends to over saturate reds, so adding some light would be a good thing (and maybe a shift in your white balance...your hands and face look a little on the red side).<br/><br/><br/><i>Message edited by author 2006-10-26 19:12:29.</i></td>', 'hm...tough to light indeed without proper studio gear.  The first thing i notice is that it''s strongly lit from the right side.  this casts strong shadows from you, the cup, the bowl, and the paper.  a second source of light (same strength as the first one, or slightly less) placed behind the camera and slightly to the left would fill this in nicely.  Some shadow is good - it adds depth and contour to the photo - but shots like this need more even lighting i think.  Lower light also tends to over saturate reds, so adding some light would be a good thing (and maybe a shift in your white balance...your hands and face look a little on the red side).', '2006-10-19 11:35:25.000000', '2006-10-26 20:12:29.000000', 1),
(2943595, 412230, 31403, '<td valign="top">more contrast would make this stronger IMO</td>', 'more contrast would make this stronger IMO', '2006-10-19 11:36:52.000000', NULL, 1),
(2943599, 410470, 6388, '<td valign="top">Magnificent.  best in show.  you''ve captured that 1950s nostalgia perfectly, right down to the square crop with the big border...I feel like i''m going through my dad''s old photo boxes.<br/> <br/>lurve it.</td>', 'Magnificent.  best in show.  you''ve captured that 1950s nostalgia perfectly, right down to the square crop with the big border...I feel like i''m going through my dad''s old photo boxes. lurve it.', '2006-10-19 11:37:36.000000', NULL, 1),
