(2946842, 412318, 64175, '<td valign="top">A little too much flare in the corner for me.  6.</td>', 'A little too much flare in the corner for me.  6.', '2006-10-20 11:28:28.000000', NULL, 1),
(2946844, 410481, 64175, '<td valign="top">The colors of the baloons are fantastic and the composition of the shot is as well. But the image as a whole looks rather flat and does not give the depth needed to see where balloons are in position to one another.</td>', 'The colors of the baloons are fantastic and the composition of the shot is as well. But the image as a whole looks rather flat and does not give the depth needed to see where balloons are in position to one another.', '2006-10-20 11:28:59.000000', NULL, 1),
