(2947070, 410907, 32161, '<td valign="top">Wow! 10 from me. Best photo, 1st prize! really really nice.</td>', 'Wow! 10 from me. Best photo, 1st prize! really really nice.', '2006-10-20 13:38:45.000000', NULL, 1),
