INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2948434, 410481, 23511, '<td valign="top">I didn''t get out there this year - but I know there were few opportunities for this photo this year.<br/>Good luck!</td>', 'I didn''t get out there this year - but I know there were few opportunities for this photo this year.Good luck!', '2006-10-21 01:37:34.000000', NULL, 1),
(2948455, 411866, 23511, '<td valign="top">Though likely accurate for most, probably a little to graphic.</td>', 'Though likely accurate for most, probably a little to graphic.', '2006-10-21 01:59:15.000000', NULL, 1),
(2948528, 411772, 35545, '<td valign="top">I really don''t like the tilt in ths shot.  It makes it look like the food is going to fall off the plate!</td>', 'I really don''t like the tilt in ths shot.  It makes it look like the food is going to fall off the plate!', '2006-10-21 04:22:31.000000', NULL, 1),
(2948540, 412310, 8860, '<td valign="top">Very pretty - its appeal coming from the over saturation and pools of blue sky and radiant autumn leaves. Proficiently shot, if a little lacking in any clear focal interest beyond those leaves.</td>', 'Very pretty - its appeal coming from the over saturation and pools of blue sky and radiant autumn leaves. Proficiently shot, if a little lacking in any clear focal interest beyond those leaves.', '2006-10-21 04:39:15.000000', NULL, 1),
(2948541, 412257, 8860, '<td valign="top">Like the little trail to the hole - you just needed a bit more power and that could have been down.<br/>: J</td>', 'Like the little trail to the hole - you just needed a bit more power and that could have been down.: J', '2006-10-21 04:40:44.000000', NULL, 1),
(2948542, 412320, 8860, '<td valign="top">Great title and nice idea. Composition is a bit weak. I would like to have seen a grave stone closer with less over-exposed sky.</td>', 'Great title and nice idea. Composition is a bit weak. I would like to have seen a grave stone closer with less over-exposed sky.', '2006-10-21 04:43:38.000000', NULL, 1),
(2948544, 412054, 8860, '<td valign="top">Expertly shot, but I honestly don''t know what you''re trying to say with this. What I mean is: is this you in the shower every morning? In which case why the menacing look? On the other hand, if you''ve just strangled your sister in the bathroom then this is just dandy.<br/>: J</td>', 'Expertly shot, but I honestly don''t know what you''re trying to say with this. What I mean is: is this you in the shower every morning? In which case why the menacing look? On the other hand, if you''ve just strangled your sister in the bathroom then this is just dandy.: J', '2006-10-21 04:53:24.000000', NULL, 1),
(2948668, 410470, 31443, '<td valign="top">Coming back for comment, I think I know who this is but won''t dare say just in case ;) I just love this shot so much, just says so much and reminds me of my mom in the sixties :) gave you a 10 first round, that stays ofcourse..</td>', 'Coming back for comment, I think I know who this is but won''t dare say just in case ;) I just love this shot so much, just says so much and reminds me of my mom in the sixties :) gave you a 10 first round, that stays ofcourse..', '2006-10-21 09:09:14.000000', NULL, 1),
(2948685, 411751, 32345, '<td valign="top">A dream place, i wanna be there.</td>', 'A dream place, i wanna be there.', '2006-10-21 09:32:20.000000', NULL, 1),
(2948698, 412323, 13666, '<td valign="top">Definite Wow from me. Hope you share how you did that afterwards! ;-)</td>', 'Definite Wow from me. Hope you share how you did that afterwards! ;-)', '2006-10-21 09:53:26.000000', NULL, 1),
(2948699, 411801, 13666, '<td valign="top">Love the negative space here.</td>', 'Love the negative space here.', '2006-10-21 09:54:07.000000', NULL, 1),
(2948702, 412054, 13666, '<td valign="top">Guy is not really my type, but you get points for the technical aspects. ;) Love the high contrast, the water is photographed really really well, love the detail (ven down to his stubble!).</td>', 'Guy is not really my type, but you get points for the technical aspects. ;) Love the high contrast, the water is photographed really really well, love the detail (ven down to his stubble!).', '2006-10-21 09:55:31.000000', NULL, 1),
(2948726, 411178, 4010, '<td valign="top">To me this does not realy capture the nature of the challenge without the caption.  Good shot though.</td>', 'To me this does not realy capture the nature of the challenge without the caption.  Good shot though.', '2006-10-21 10:18:20.000000', NULL, 1),
(2948729, 412122, 4010, '<td valign="top">Interesting shot, nice textures.  Does not realy invoke the nature of the challenge without the caption though.</td>', 'Interesting shot, nice textures.  Does not realy invoke the nature of the challenge without the caption though.', '2006-10-21 10:19:15.000000', NULL, 1),
(2948733, 411204, 4010, '<td valign="top">I really like this shot.  Very creative.  I had to take off a little because, for me, it just does not totaly give me the sense of "morning"</td>', 'I really like this shot.  Very creative.  I had to take off a little because, for me, it just does not totaly give me the sense of "morning"', '2006-10-21 10:20:49.000000', NULL, 1),
(2948844, 411916, 67413, '<td valign="top">This is an exquisite capture!<br/>Composition is excellent, as it is very easy for your eyes to scan the image from foreground to background, and even in different ''roadmaps''.<br/>There are many nice finds, although I wish that the photo could be enlarged to see more detail.<br/>I can only imagine that the original must be very Beautiful.<br/>A 20''x30'' appx would be awesome, matted in the darkest green visible, and a small black frame that just covers the edge of the mat.<br/> <br/>Great photo!<br/>Rohn</td>', 'This is an exquisite capture!Composition is excellent, as it is very easy for your eyes to scan the image from foreground to background, and even in different ''roadmaps''.There are many nice finds, although I wish that the photo could be enlarged to see more detail.I can only imagine that the original must be very Beautiful.A 20''x30'' appx would be awesome, matted in the darkest green visible, and a small black frame that just covers the edge of the mat. Great photo!Rohn', '2006-10-21 11:53:13.000000', NULL, 1),
(2948848, 412316, 54705, '<td valign="top">Thats a Great Shot, Beautiful</td>', 'Thats a Great Shot, Beautiful', '2006-10-21 11:56:40.000000', NULL, 1),
(2948850, 412136, 54705, '<td valign="top">I can smell the freshness.</td>', 'I can smell the freshness.', '2006-10-21 11:58:01.000000', NULL, 1),
(2948851, 412318, 54705, '<td valign="top">Thats a Beautiful Tree. Nice shot.</td>', 'Thats a Beautiful Tree. Nice shot.', '2006-10-21 11:58:33.000000', NULL, 1),
(2948853, 411190, 54705, '<td valign="top">WOW, I wish I was there.</td>', 'WOW, I wish I was there.', '2006-10-21 12:00:19.000000', NULL, 1),
(2948855, 410670, 54705, '<td valign="top">That looks Heavenly</td>', 'That looks Heavenly', '2006-10-21 12:01:48.000000', NULL, 1),
(2948858, 412281, 54705, '<td valign="top">Very Moving, Nice shot. Something about the peace of the sea and the raging red clouds.</td>', 'Very Moving, Nice shot. Something about the peace of the sea and the raging red clouds.', '2006-10-21 12:03:59.000000', NULL, 1),
(2948862, 409522, 54705, '<td valign="top">Nice shot, Is the person looking at the sunrise or at the camera. Hard to tell, thats pretty cool.</td>', 'Nice shot, Is the person looking at the sunrise or at the camera. Hard to tell, thats pretty cool.', '2006-10-21 12:08:56.000000', NULL, 1),
(2948863, 412172, 54705, '<td valign="top">That looks lovely, great shot.</td>', 'That looks lovely, great shot.', '2006-10-21 12:10:08.000000', NULL, 1),
(2948865, 409063, 67413, '<td valign="top">What a wonderful surprise and way to start the day!<br/>She looks as surprised as you probably were.<br/>A "deer" in the morning or a "dear" in the morning keeps you smiling all day!<br/> <br/>Very Nice<br/>Rohn</td>', 'What a wonderful surprise and way to start the day!She looks as surprised as you probably were.A "deer" in the morning or a "dear" in the morning keeps you smiling all day! Very NiceRohn', '2006-10-21 12:10:30.000000', NULL, 1),
(2948868, 411916, 54705, '<td valign="top">WOW, Beautiful photo, I would love to visit where ever that is.</td>', 'WOW, Beautiful photo, I would love to visit where ever that is.', '2006-10-21 12:14:01.000000', NULL, 1),
(2948875, 412087, 54705, '<td valign="top">Thats a beautiful Church, Nice shot.</td>', 'Thats a beautiful Church, Nice shot.', '2006-10-21 12:20:51.000000', NULL, 1),
(2948878, 411580, 54705, '<td valign="top">Great, really shows how small we are.</td>', 'Great, really shows how small we are.', '2006-10-21 12:21:50.000000', NULL, 1),
(2948988, 411291, 67413, '<td valign="top">EXCELLENT!<br/>Great composition.<br/>Perfect exposure on colors.<br/>A bit gross, but Life in Nature.<br/>You sure nailed the focus.<br/> <br/>All around Great Picture!<br/>Well done!<br/>Rohn</td>', 'EXCELLENT!Great composition.Perfect exposure on colors.A bit gross, but Life in Nature.You sure nailed the focus. All around Great Picture!Well done!Rohn', '2006-10-21 13:24:51.000000', NULL, 1),
(2948999, 411568, 67413, '<td valign="top">Beautiful Picture!<br/>Excellent capture.<br/>Nice composition.<br/>Good colors.<br/> <br/>The Right place at the Right moment<br/>An enjoyable scene.<br/>Rohn</td>', 'Beautiful Picture!Excellent capture.Nice composition.Good colors. The Right place at the Right momentAn enjoyable scene.Rohn', '2006-10-21 13:28:50.000000', NULL, 1),
(2949011, 411886, 67413, '<td valign="top">This is what makes being there to watch Sunrise, gratifying!<br/>God creates incredibly awesome Sunrises... somewhere... every day!<br/> <br/>What an wonderful way to start the day... and the Memory you make will last all day, and then some...<br/> <br/>The colors just blow you away!<br/>Needless to say, "I Like It"!<br/>Rohn</td>', 'This is what makes being there to watch Sunrise, gratifying!God creates incredibly awesome Sunrises... somewhere... every day! What an wonderful way to start the day... and the Memory you make will last all day, and then some... The colors just blow you away!Needless to say, "I Like It"!Rohn', '2006-10-21 13:38:52.000000', NULL, 1),
(2949064, 412174, 50034, '<td valign="top">Funny!  A poster made back in the 70''s featured a lion with pretty much this expression and included the caption, <b>"I''m not worth a D__N without my morning coffee!"</b>  (The word was spelled out, however.)  I found out about the poster because even though it was hung on the back of the door in the Teacher''s Lounge, <b><i>the band director during my senior year was "kind" enough to pose right next to it with a coffee-cup salute &amp; a smile!</i></b>  :)</td>', 'Funny!  A poster made back in the 70''s featured a lion with pretty much this expression and included the caption, "I''m not worth a D__N without my morning coffee!"  (The word was spelled out, however.)  I found out about the poster because even though it was hung on the back of the door in the Teacher''s Lounge, the band director during my senior year was "kind" enough to pose right next to it with a coffee-cup salute & a smile!  :)', '2006-10-21 14:24:11.000000', NULL, 1),
(2949084, 411423, 50034, '<td valign="top">My life on work days:  <b>Breakfast in a glass while I scramble!</b>  ;)</td>', 'My life on work days:  Breakfast in a glass while I scramble!  ;)', '2006-10-21 14:29:56.000000', NULL, 1),
(2949086, 412054, 50034, '<td valign="top">Don''t feel bad!  They call me a "Drip," too!  ;)</td>', 'Don''t feel bad!  They call me a "Drip," too!  ;)', '2006-10-21 14:30:50.000000', NULL, 1),
(2949089, 412229, 50034, '<td valign="top">Challenge entry?  I''m flushed!!!!  ;}</td>', 'Challenge entry?  I''m flushed!!!!  ;}', '2006-10-21 14:31:42.000000', NULL, 1),
(2949091, 412308, 50034, '<td valign="top">...And...How!  :)</td>', '...And...How!  :)', '2006-10-21 14:32:10.000000', NULL, 1),
