(2949094, 411376, 50034, '<td valign="top">Just think of it another way...This is one way to get a <i>grip on yourself</i> before a nerve-wracking presentation!  ;)</td>', 'Just think of it another way...This is one way to get a grip on yourself before a nerve-wracking presentation!  ;)', '2006-10-21 14:34:58.000000', NULL, 1),
(2949099, 410763, 50034, '<td valign="top">...With a couple of principals watching each other''s backs as well as watching to see that none of the children ''cut in line'' or ''forget the rules'' on the ''playground.''  ;)</td>', '...With a couple of principals watching each other''s backs as well as watching to see that none of the children ''cut in line'' or ''forget the rules'' on the ''playground.''  ;)', '2006-10-21 14:38:27.000000', NULL, 1),
(2949108, 412096, 67152, '<td valign="top">Nice face, but I think the caption is a stretch</td>', 'Nice face, but I think the caption is a stretch', '2006-10-21 14:47:30.000000', NULL, 1),
(2949113, 410813, 67152, '<td valign="top">Simple idea -  nice use of light and shadows</td>', 'Simple idea -  nice use of light and shadows', '2006-10-21 14:50:44.000000', NULL, 1),
(2949115, 412040, 67152, '<td valign="top">Well done - very nice use of composition.  The contrast of the crossword and the steaming cup make this a really nice shot.</td>', 'Well done - very nice use of composition.  The contrast of the crossword and the steaming cup make this a really nice shot.', '2006-10-21 14:51:40.000000', NULL, 1),
(2949120, 411662, 67152, '<td valign="top">Very peaceful location - but I am of the opinion that there is an over-use of editing techniques.</td>', 'Very peaceful location - but I am of the opinion that there is an over-use of editing techniques.', '2006-10-21 14:53:03.000000', NULL, 1),
(2949124, 412199, 67152, '<td valign="top">I really like the composition of this photo but the color and contrast seem a little too subdued for my taste - either that or my monitor is on the fritz!</td>', 'I really like the composition of this photo but the color and contrast seem a little too subdued for my taste - either that or my monitor is on the fritz!', '2006-10-21 14:54:22.000000', NULL, 1),
(2949126, 412216, 67152, '<td valign="top">I sure like this photo - it is so peaceful and you can almost hear the tide.  Great job capturing a quiet moment.</td>', 'I sure like this photo - it is so peaceful and you can almost hear the tide.  Great job capturing a quiet moment.', '2006-10-21 14:55:56.000000', NULL, 1),
(2949130, 411192, 67152, '<td valign="top">An award winner if I every saw one.  Great composition and excellent use of light to capture Morning all over the USA.</td>', 'An award winner if I every saw one.  Great composition and excellent use of light to capture Morning all over the USA.', '2006-10-21 14:56:40.000000', NULL, 1),
(2949147, 412295, 61803, '<td valign="top">kewl</td>', 'kewl', '2006-10-21 15:06:32.000000', NULL, 1),
(2949174, 412040, 4010, '<td valign="top">I think this was the best of the many cofee shots I saw for this challenge.  Very nicely done.</td>', 'I think this was the best of the many cofee shots I saw for this challenge.  Very nicely done.', '2006-10-21 15:35:58.000000', NULL, 1),
(2949178, 411219, 4010, '<td valign="top">The flares from the lights and the hot spot in upper right corner take away from the image.    Interesting idea though.  Clever play on words with the old sailors warning.</td>', 'The flares from the lights and the hot spot in upper right corner take away from the image.    Interesting idea though.  Clever play on words with the old sailors warning.', '2006-10-21 15:39:35.000000', NULL, 1),
(2949279, 410229, 66262, '<td valign="top">This looks more like midday to me.  Nothing really stands out to evoke the feeling of morning.  Nice tonal range though.</td>', 'This looks more like midday to me.  Nothing really stands out to evoke the feeling of morning.  Nice tonal range though.', '2006-10-21 16:47:40.000000', NULL, 1),
(2949281, 411600, 66262, '<td valign="top">Very nice, the fog adds a wonderful atmospheric effect and helps smooth the transition from hard silhouette to a soft background.</td>', 'Very nice, the fog adds a wonderful atmospheric effect and helps smooth the transition from hard silhouette to a soft background.', '2006-10-21 16:48:42.000000', NULL, 1),
(2949283, 412067, 66262, '<td valign="top">Beautiful colors.</td>', 'Beautiful colors.', '2006-10-21 16:49:07.000000', NULL, 1),
(2949285, 412323, 66262, '<td valign="top">Interesting perspective.  Wouldn''t think somebody would be throwing two alarms at once though.</td>', 'Interesting perspective.  Wouldn''t think somebody would be throwing two alarms at once though.', '2006-10-21 16:50:09.000000', NULL, 1),
(2949287, 411070, 66262, '<td valign="top">Looks like a photo from a bed and breakfast pamphlet, somewhat bland subject matter.</td>', 'Looks like a photo from a bed and breakfast pamphlet, somewhat bland subject matter.', '2006-10-21 16:51:11.000000', NULL, 1),
(2949330, 411866, 66262, '<td valign="top">Lovely.</td>', 'Lovely.', '2006-10-21 17:08:25.000000', NULL, 1),
