(2949394, 411855, 66262, '<td valign="top">???  If I weren''t familiar with the unmistakable starbucks logo, I''d have no idea what any of this stuff was, or how it would correlate with morning.</td>', '???  If I weren''t familiar with the unmistakable starbucks logo, I''d have no idea what any of this stuff was, or how it would correlate with morning.', '2006-10-21 17:24:31.000000', NULL, 1),
(2949399, 412096, 66262, '<td valign="top">What would people think if you weren''t allowed to title your piece?</td>', 'What would people think if you weren''t allowed to title your piece?', '2006-10-21 17:25:57.000000', NULL, 1),
(2949468, 412204, 55838, '<td valign="top">This shot is tremendous.  Kind of a documentary eh?  So clean - love the color tones you chose...I even love your attire!  Looks like a yucky ritual but one good thing comes of it...an 8 from me!</td>', 'This shot is tremendous.  Kind of a documentary eh?  So clean - love the color tones you chose...I even love your attire!  Looks like a yucky ritual but one good thing comes of it...an 8 from me!', '2006-10-21 17:57:47.000000', NULL, 1),
(2949487, 412232, 55838, '<td valign="top">Mmmmmmm...looks fabulous.  Great colors and composition, perfect border and interesting crop.  Back to bump to 8.</td>', 'Mmmmmmm...looks fabulous.  Great colors and composition, perfect border and interesting crop.  Back to bump to 8.', '2006-10-21 18:17:48.000000', NULL, 1),
